from scipy.spatial.transform import Rotation as Rot
from PIL import Image

class Controller:
 def __init__(self):
  self.s=rcb_dtb.Session(); self.m=self.s.model; self.d=self.s.data
  self.k=mujoco.MjData(self.m); self.bid=self.m.body('palmleft_hand_C_MC').id
  self.q=rcb_dtb.INIT_Q.copy(); self.s.record_start()
 def pose(self):return self.d.xpos[self.bid].copy(),self.d.xmat[self.bid].reshape(3,3).copy()
 def ik(self,p,R,q=None):
  q=self.q.copy() if q is None else q.copy(); self.k.qpos[:]=self.d.qpos
  for i in range(100):
   self.k.qpos[self.s._jq]=q;mujoco.mj_forward(self.m,self.k)
   e=np.r_[p-self.k.xpos[self.bid],Rot.from_matrix(R@self.k.xmat[self.bid].reshape(3,3).T).as_rotvec()]
   if np.linalg.norm(e)<1e-5:break
   jp=np.zeros((3,self.m.nv));jr=jp.copy();mujoco.mj_jacBody(self.m,self.k,jp,jr,self.bid)
   J=np.r_[jp[:,:7],jr[:,:7]]; dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*.0001,e)
   q[:7]+=dq*np.minimum(1,.15/(np.max(np.abs(dq))+1e-9));q=np.clip(q,self.s.lower,self.s.upper)
  return q
 def move(self,p=None,R=None,hand=None,n=120):
  a=self.q.copy(); p0,R0=self.pose(); p=p0 if p is None else np.array(p);R=R0 if R is None else R
  rv=Rot.from_matrix(R@R0.T).as_rotvec()
  for i in range(n):
