   self.q=q;self.s.step(q)
  return self.s.progress()
 def hold(self,n=60):
  for _ in range(n):self.s.step(self.q)
 def snap(self,name):
  for cam in ['front','side','oblique']:Image.fromarray(self.s.render(cam)).resize((960,720)).save('/app/output/'+name+'_'+cam+'.png')
 def report(self,name):
  print(name,self.s.progress(),'obj',self.s.state()['object_pos'], 'palm',self.pose()[0],flush=True)
  for c in self.d.contact:
   b1=self.m.geom_bodyid[c.geom1];b2=self.m.geom_bodyid[c.geom2]
   if self.s._obj in [b1,b2]:print('contact',self.m.geom(c.geom1).name,self.m.geom(c.geom2).name,round(c.dist,4),flush=True)

def handclose(v=1.3):
 h=np.zeros(22);h[:5]=[1.2,0,.5,0,.8]
 for j in [5,9,13,18]:h[j]=v;h[j+2]=v;h[j+3]=v*.7
 return h

def main():
 c=Controller();s=c.s
 # Hand x down, y follows handle, z forward. Align handle perpendicular to fingers.
 yaw=.134
 R=Rot.from_euler('z',yaw).as_matrix()@np.array([[0,1,0],[0,0,-1],[-1,0,0.]])
 p=np.array([.255,.169,.608])
 c.move(p+[0,0,.14],R,n=180);c.move(p,R,n=180);c.report('approach');c.snap('approach')
 c.move(hand=handclose(),n=180);c.hold();c.report('close');c.snap('close')
 c.move(p+[0,0,.13],R,n=180);c.hold();c.report('lift');c.snap('lift')
 A=s.record_stop();s.save_trajectory(A);np.savez('/app/output/teststate.npz',qpos=c.d.qpos,qvel=c.d.qvel,q=c.q)
if __name__=='__main__':main()
